async function scanBundle(input, deliver) {
  const decoder = new TextDecoder("utf-8");
  let pending = "";
  let line = 1;
  let delivered = 0;
  let stopped = false;

  const processLine = async (text, lineNumber) => {
    if (/^[ \t\r]*$/.test(text)) return false;

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      const error = new Error(`Invalid JSON on line ${lineNumber}`);
      error.code = "BAD_LINE";
      error.line = lineNumber;
      throw error;
    }

    delivered++;
    if ((await deliver(value, lineNumber)) === false) {
      stopped = true;
      return true;
    }
    return false;
  };

  const processText = async (text) => {
    pending += text;

    while (!stopped) {
      const newline = pending.indexOf("\n");
      if (newline === -1) break;

      let current = pending.slice(0, newline);
      pending = pending.slice(newline + 1);

      if (current.endsWith("\r")) {
        current = current.slice(0, -1);
      }

      if (await processLine(current, line)) return true;
      line++;
    }

    return stopped;
  };

  try {
    while (!stopped) {
      const chunk = await input.read();
      if (chunk === null) break;

      if (await processText(decoder.decode(chunk, { stream: true }))) {
        break;
      }
    }

    if (!stopped) {
      if (await processText(decoder.decode())) {
        return delivered;
      }

      if (pending.length > 0) {
        await processLine(pending, line);
      }
    }

    return delivered;
  } finally {
    await input.close();
  }
}
